/// Resolves binary body bytes from params + context.
///
/// Accepts one of:
/// - `body_var`: variable name in `context.local`; resolved from `DataRef::Blob` (BlobStore claim)
///   or `DataRef::Inline` (string as UTF-8, other JSON values serialized)
/// - `body_base64`: inline base64-encoded string, decoded to raw bytes
fn resolve_binary_body(params: &Value, context: &mut ToolContext) -> Result<Vec<u8>> {
    if let Some(var_name) = params.get("body_var").and_then(|v| v.as_str()) {
        let data_ref = context
            .local
            .get(var_name)
            .ok_or_else(|| anyhow!("body_var '{}' not found in context", var_name))?;

        let bytes = match data_ref {
            DataRef::Blob(ticket) => {
                let store = context
                    .store
                    .ok_or_else(|| anyhow!("BlobStore not available to resolve body_var '{}'", var_name))?;
                store
                    .claim(ticket)
                    .with_context(|| format!("Failed to claim blob for body_var '{}'", var_name))?
            }
            DataRef::Inline(Value::String(s)) => s.as_bytes().to_vec(),
            DataRef::Inline(other) => serde_json::to_vec(other)
                .with_context(|| format!("Failed to serialize inline value for body_var '{}'", var_name))?,
        };

        return Ok(bytes);
    }

    if let Some(b64) = params.get("body_base64").and_then(|v| v.as_str()) {
        return general_purpose::STANDARD
            .decode(b64)
            .context("Failed to decode body_base64");
    }

    Err(anyhow!("Binary body requires either 'body_var' or 'body_base64'"))
}

impl Tool for HttpClientTool {
    fn id(&self) -> &'static str {
        "http_client"
    }

    fn run(&self, context: &mut ToolContext, params: Value) -> Result<Value> {
        // Shadow Mode Interception
        if context.shadow_mode {
            let mock = context.shadow_masks.get(self.id());
            tracing::info!(
                tool = self.id(),
                mock_found = mock.is_some(),
                "Shadow Mode: Intercepting HTTP request"
            );

            if let Some(cfg) = mock {
                if cfg.delay_ms > 0 {
                    std::thread::sleep(std::time::Duration::from_millis(cfg.delay_ms));
                }
                return Ok(cfg.return_value.clone());
            }

            return Ok(serde_json::json!({
                "status": 200,
                "body": { "message": "Shadow Mode: Request Intercepted" },
                "headers": {}
            }));
        }

        let url = params
            .get("url")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing 'url'"))?;

        let method = params
            .get("method")
            .and_then(|v| v.as_str())
            .unwrap_or("GET");

        let body = params.get("body");
        let headers_val = params.get("headers");
        let connection_slug = params.get("connection").and_then(|v| v.as_str());
        let aws_auth = params.get("aws_auth");

        let mut aws_config = aws_auth.and_then(|v| {
            let service = v.get("service")?.as_str()?.to_string();
            let region = v.get("region")?.as_str()?.to_string();
            let access_key = v.get("access_key")?.as_str()?.to_string();
            let secret_key = v.get("secret_key")?.as_str()?.to_string();
            Some(AwsSigV4Config { service, region, access_key, secret_key })
        });

        // 1. Connection Resolution (Auth + Base URL)
        let (resolved_url, dynamic_headers) =
            resolve_connection_auth(url, connection_slug, context)?;

        // Fallback to connection-based AWS auth if not explicitly provided
        if aws_config.is_none()
            && let Some(slug) = connection_slug
            && let Some(resolver) = context.secrets
            && let Ok(conn_data) = resolver.resolve_connection(&ferroflux_iam::TenantId::from("default_tenant"), slug)
            && let Some("aws_sigv4") = conn_data.get("auth_type").and_then(|v| v.as_str())
        {
            let service = params.get("aws_service").and_then(|v| v.as_str()).unwrap_or("s3").to_string();
            let region = conn_data.get("region").and_then(|v| v.as_str())
                .or_else(|| params.get("aws_region").and_then(|v| v.as_str()))
                .unwrap_or("us-east-1").to_string();
            let access_key = conn_data.get("access_key").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let secret_key = conn_data.get("secret_key").and_then(|v| v.as_str()).unwrap_or("").to_string();

            if !access_key.is_empty() && !secret_key.is_empty() {
                aws_config = Some(AwsSigV4Config { service, region, access_key, secret_key });
            }
        }

        // 2. SSRF Protection
        check_ssrf(&resolved_url)?;

        // 3. Execute — branch on stream or body_type
        let stream = params.get("stream").and_then(|v| v.as_bool()).unwrap_or(false);
        let body_type = params.get("body_type").and_then(|v| v.as_str()).unwrap_or("json");
        let client = reqwest::blocking::Client::new();

        if stream {
            let step_id = params
                .get("step_id")
                .and_then(|v| v.as_str())
                .unwrap_or("http_client");

            let req = BlockingRequest::new(&client, &resolved_url, method)
                .with_headers(headers_val, &dynamic_headers)
                .with_body(body)
                .with_aws(aws_config.as_ref());

            let (status, headers, body_val) = execute_streaming_request(
                req,
                context.event_bus.as_ref(),
                &context.trace_id,
                step_id,
            )?;

            return Ok(serde_json::json!({
                "status": status,
                "headers": headers,
                "body": body_val
            }));
        }

        let response_type = params.get("response_type").and_then(|v| v.as_str()).unwrap_or("json");

        let (status, headers, body_val) = if response_type == "blob" {
            let req = BlockingRequest::new(&client, &resolved_url, method)
                .with_headers(headers_val, &dynamic_headers)
                .with_body(body)
                .with_aws(aws_config.as_ref());

            let (status, headers, bytes) = execute_raw_request(req)?;

            let store = context
                .store
                .ok_or_else(|| anyhow!("BlobStore not available in context"))?;
            let ticket = store.check_in_with_metadata(&bytes, headers.clone())?;
            (status, headers, serde_json::to_value(ticket)?)
        } else if body_type == "multipart" {
            let parts = params
                .get("parts")
                .and_then(|v| v.as_array())
                .ok_or_else(|| anyhow!("Missing 'parts' array for multipart body"))?;
            let form = build_multipart_form(parts, context)?;

            execute_multipart_request(
                &client,
                &resolved_url,
                method,
                headers_val,
                &dynamic_headers,
                form,
                aws_config.as_ref(),
            )?
        } else if body_type == "binary" {
            let content_type = params
                .get("content_type")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow!("Missing 'content_type' for binary body"))?;
            let bytes = resolve_binary_body(&params, context)?;

            let req = BlockingRequest::new(&client, &resolved_url, method)
                .with_headers(headers_val, &dynamic_headers)
                .with_aws(aws_config.as_ref());

            execute_binary_request(req, bytes, content_type)?
        } else {
            let req = BlockingRequest::new(&client, &resolved_url, method)
                .with_headers(headers_val, &dynamic_headers)
                .with_body(body)
                .with_aws(aws_config.as_ref());

            execute_request(req)?
        };

        Ok(serde_json::json!({
            "status": status,
            "headers": headers,
            "body": body_val
        }))
    }
}

/// Builds a `multipart/form-data` form from a JSON `parts` array.
///
/// Each element in `parts` must have a `name` field and exactly one content source:
/// - `content`: literal text string
/// - `content_json`: any JSON value (serialized to string)
/// - `content_var`: variable name to look up in `context.local` (supports blobs)
///
/// Optional per-part fields: `filename`, `content_type`.
pub fn build_multipart_form(
    parts: &[Value],
    context: &ToolContext,
) -> Result<reqwest::blocking::multipart::Form> {
    let mut form = reqwest::blocking::multipart::Form::new();

    for part_val in parts {
        let name = part_val
            .get("name")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow!("Multipart part missing required 'name' field"))?
            .to_string();

        let filename = part_val.get("filename").and_then(|v| v.as_str()).map(str::to_string);
        let mime_override = part_val.get("content_type").and_then(|v| v.as_str()).map(str::to_string);

        let mut part: reqwest::blocking::multipart::Part =
            if let Some(text) = part_val.get("content").and_then(|v| v.as_str()) {
                reqwest::blocking::multipart::Part::text(text.to_string())
            } else if let Some(json_val) = part_val.get("content_json") {
                let s = serde_json::to_string(json_val)
                    .context("Failed to serialize content_json")?;
                reqwest::blocking::multipart::Part::text(s)
            } else if let Some(var_name) = part_val.get("content_var").and_then(|v| v.as_str()) {
                let data_ref = context
                    .local
                    .get(var_name)
                    .ok_or_else(|| anyhow!("content_var '{}' not found in context.local", var_name))?;

                match data_ref {
                    DataRef::Inline(Value::String(s)) => {
                        reqwest::blocking::multipart::Part::text(s.clone())
                    }
                    DataRef::Inline(other) => {
                        let s = serde_json::to_string(other)
                            .context("Failed to serialize inline DataRef")?;
                        reqwest::blocking::multipart::Part::text(s)
                    }
                    DataRef::Blob(ticket) => {
                        let bytes = context
                            .store
                            .ok_or_else(|| anyhow!("BlobStore not available in ToolContext"))?
                            .claim(ticket)
                            .context("Failed to claim blob from BlobStore")?;

                        // Use explicit content_type, then ticket metadata, then nothing
                        let effective_mime = mime_override
                            .as_deref()
                            .or_else(|| ticket.metadata.get("content_type").map(|s| s.as_str()));

                        let mut p = reqwest::blocking::multipart::Part::bytes(bytes);
                        if let Some(m) = effective_mime {
                            p = p.mime_str(m).context("Invalid MIME type")?;
                        }
                        if let Some(ref f) = filename {
                            p = p.file_name(f.clone());
                        }
                        // Return early — filename/mime already applied for blobs
                        form = form.part(name, p);
                        continue;
                    }
                }
            } else {
                return Err(anyhow!(
                    "Part '{}' has no content source: provide 'content', 'content_json', or 'content_var'",
                    name
                ));
            };

        // Apply filename and content_type to non-blob parts
        if let Some(ref f) = filename {
            part = part.file_name(f.clone());
        }
        if let Some(ref m) = mime_override {
            part = part.mime_str(m).context("Invalid MIME type")?;
        }

        form = form.part(name, part);
    }

    Ok(form)
}

/// Executes a blocking HTTP request with a multipart/form-data body.
///
/// Shares header setup with `execute_request`; sends `.multipart(form)` instead of `.json(body)`.
pub fn execute_multipart_request(
    client: &reqwest::blocking::Client,
    url: &str,
    method: &str,
    static_headers: Option<&Value>,
    dynamic_headers: &[(String, String)],
    form: reqwest::blocking::multipart::Form,
    aws_config: Option<&AwsSigV4Config>,
) -> Result<(u16, HashMap<String, String>, Value)> {
    // SigV4 for multipart is tricky because the body is complex.
    // However, S3 often uses raw binary PUT for uploads, which uses execute_binary_request.
    // For now, we'll implement it for binary and simple requests first.
    let final_dynamic_headers = dynamic_headers.to_vec();
    if let Some(_config) = aws_config {
        // Multipart signing is technically complex and requires different headers.
        // We will skip for now or implement as needed.
    }

    let mut req = match method {

        "POST" => client.post(url),
        "PUT" => client.put(url),
        "PATCH" => client.patch(url),
        _ => client.post(url), // multipart almost always POST/PUT
    };

    // Static headers from params
    if let Some(h) = static_headers.and_then(|v| v.as_object()) {
        for (k, v) in h {
            if let Some(s) = v.as_str() {
                req = req.header(k, s);
            }
        }
    }

    // Dynamic auth headers from connection and AWS SigV4
    for (k, v) in &final_dynamic_headers {
        req = req.header(k, v);
    }


    let resp = req.multipart(form).send().context("Multipart HTTP request failed")?;
    let status = resp.status().as_u16();
    let resp_headers: HashMap<String, String> = resp
        .headers()
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_str().unwrap_or("").to_string()))
        .collect();

    let text = resp.text().unwrap_or_default();
    let body_val: Value = serde_json::from_str(&text).unwrap_or(Value::String(text));

    Ok((status, resp_headers, body_val))
}

/// Executes a blocking HTTP request with a raw binary body.
///
/// Sets `Content-Type` to the provided MIME type and sends the raw bytes as the
/// request body. Use this for APIs that expect `audio/mpeg`, `image/png`,
/// `application/octet-stream`, etc.
pub fn execute_binary_request(
    req: BlockingRequest,
    bytes: Vec<u8>,
    content_type: &str,
) -> Result<(u16, HashMap<String, String>, Value)> {
    let mut final_dynamic_headers = req.dynamic_headers.to_vec();

    if let Some(config) = req.aws_config {
        // MUST include content-type in signing if we're adding it manually
        let mut combined_headers = req.dynamic_headers.to_vec();
        combined_headers.push(("Content-Type".to_string(), content_type.to_string()));
        let sig_headers = aws_sigv4::generate_sigv4_headers(config, req.method, req.url, &combined_headers, &bytes)?;
        final_dynamic_headers.extend(sig_headers);
    }

    let mut builder = match req.method {
        "POST" => req.client.post(req.url),
        "PUT" => req.client.put(req.url),
        "PATCH" => req.client.patch(req.url),
        _ => req.client.post(req.url),
    };

    // Static headers from params
    if let Some(h) = req.static_headers.and_then(|v| v.as_object()) {
        for (k, v) in h {
            if let Some(s) = v.as_str() {
                builder = builder.header(k, s);
            }
        }
    }

    // Dynamic auth headers from connection and AWS SigV4
    for (k, v) in &final_dynamic_headers {
        builder = builder.header(k, v);
    }

    builder = builder.header("Content-Type", content_type).body(bytes);

    let resp = builder.send().context("Binary HTTP request failed")?;
    let status = resp.status().as_u16();
    let resp_headers: HashMap<String, String> = resp
        .headers()
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_str().unwrap_or("").to_string()))
        .collect();

    let text = resp.text().unwrap_or_default();
    let body_val: Value = serde_json::from_str(&text).unwrap_or(Value::String(text));

    Ok((status, resp_headers, body_val))
}

/// Executes a streaming HTTP request and reads the response as Server-Sent Events (SSE).
///
/// Reads the response line-by-line using a `BufReader` (works because
/// `reqwest::blocking::Response` implements `std::io::Read`). For each `data:` line:
/// - Parses JSON and emits a `SystemEvent::StreamChunk` via the event bus
/// - Extracts text from common LLM formats (OpenAI, Anthropic, Gemini)
/// - Stops at `data: [DONE]` (OpenAI-style end marker) or end of stream
///
/// Returns `(status, headers, { "chunks": [...], "text": "...", "total_chunks": N })`.
/// `text` is the best-effort full-text accumulation from all chunks.
pub fn execute_streaming_request(
    req: BlockingRequest,
    event_bus: Option<&SystemEventBus>,
    trace_id: &str,
    step_id: &str,
) -> Result<(u16, HashMap<String, String>, Value)> {
    let mut final_dynamic_headers = req.dynamic_headers.to_vec();

    if let Some(config) = req.aws_config {
        let body_bytes = req.body.map(serde_json::to_vec).transpose()?.unwrap_or_default();
        let sig_headers = aws_sigv4::generate_sigv4_headers(config, req.method, req.url, req.dynamic_headers, &body_bytes)?;
        final_dynamic_headers.extend(sig_headers);
    }

    let mut builder = match req.method {
        "POST" => req.client.post(req.url),
        "PUT" => req.client.put(req.url),
        "PATCH" => req.client.patch(req.url),
        _ => req.client.get(req.url),
    };

    if let Some(h) = req.static_headers.and_then(|v| v.as_object()) {
        for (k, v) in h {
            if let Some(s) = v.as_str() {
                builder = builder.header(k, s);
            }
        }
    }

    for (k, v) in &final_dynamic_headers {
        builder = builder.header(k, v);
    }

    if let Some(b) = req.body {
        builder = builder.json(b);
    }

    let resp = builder.send().context("Streaming HTTP request failed")?;
    let status = resp.status().as_u16();
    let resp_headers: HashMap<String, String> = resp
        .headers()
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_str().unwrap_or("").to_string()))
        .collect();

    let reader = BufReader::new(resp);
    let mut chunks: Vec<Value> = Vec::new();
    let mut text_parts: Vec<String> = Vec::new();

    for line in reader.lines() {
        let line = line.context("Error reading SSE stream")?;

        // Skip empty lines (SSE keep-alive / event separators) and non-data lines
        if !line.starts_with("data:") {
            continue;
        }

        let data = line["data:".len()..].trim();

        if data == "[DONE]" {
            if let Some(bus) = event_bus {
                let _ = bus.0.send(SystemEvent::StreamChunk {
                    trace_id: trace_id.to_string(),
                    step_id: step_id.to_string(),
                    chunk: String::new(),
                    done: true,
                });
            }
            break;
        }

        let parsed: Value = match serde_json::from_str(data) {
            Ok(v) => v,
            Err(_) => continue, // Skip non-JSON data lines
        };

        let text_chunk = extract_stream_text(&parsed);

        if let Some(bus) = event_bus {
            let _ = bus.0.send(SystemEvent::StreamChunk {
                trace_id: trace_id.to_string(),
                step_id: step_id.to_string(),
                chunk: text_chunk.clone().unwrap_or_default(),
                done: false,
            });
        }

        if let Some(t) = text_chunk {
            text_parts.push(t);
        }

        chunks.push(parsed);
    }

    let full_text = text_parts.join("");
    let total_chunks = chunks.len();
    let body_val = serde_json::json!({
        "chunks": chunks,
        "text": full_text,
        "total_chunks": total_chunks
    });

    Ok((status, resp_headers, body_val))
}

/// Extracts the text delta from common LLM streaming response chunk formats.
///
/// Tries (in order):
/// 1. **OpenAI / Azure OpenAI**: `choices[0].delta.content`
/// 2. **Anthropic**: `delta.text` (from `content_block_delta` events)
/// 3. **Google Gemini**: `candidates[0].content.parts[0].text`
///
/// Returns `None` if none of the paths match (e.g. metadata-only chunks).
fn extract_stream_text(chunk: &Value) -> Option<String> {
    // OpenAI / Azure OpenAI
    if let Some(s) = chunk
        .get("choices")
        .and_then(|c| c.get(0))
        .and_then(|c| c.get("delta"))
        .and_then(|d| d.get("content"))
        .and_then(|v| v.as_str())
    {
        return Some(s.to_string());
    }

    // Anthropic (content_block_delta event)
    if let Some(s) = chunk
        .get("delta")
        .and_then(|d| d.get("text"))
        .and_then(|v| v.as_str())
    {
        return Some(s.to_string());
    }

    // Google Gemini
    if let Some(s) = chunk
        .get("candidates")
        .and_then(|c| c.get(0))
        .and_then(|c| c.get("content"))
        .and_then(|c| c.get("parts"))
        .and_then(|p| p.get(0))
        .and_then(|p| p.get("text"))
        .and_then(|v| v.as_str())
    {
        return Some(s.to_string());
    }

    None
}
